mapper.select:
select material_code as product_code,SUM(product_quantity) as total_quantity from ${tableName} WHERE AND material_code IS NOT NULL AND type =1 AND delete_flag = false AND enterprise_code = #{enterpriseCode}
AND record_time >= #{startDate}
AND record_time <= #{endDate}
GROUP BY material_code ORDER BY total_quantity DESC LIMIT 10

SELECT
material_code,
MIN(product_unit_price) as min_price
FROM
${tableName}
WHERE
material_code IN

    #{materialCode}

AND enterprise_code = #{enterpriseCode}
AND delete_flag = 'f'
AND type = #{type}
AND payment_strategy = #{paymentStrategy}
AND opposite = #{opposite}
GROUP BY
material_code

select SUM(product_rmb_total_price)
FROM ${tableName}
WHERE
type =1
AND delete_flag = false
AND enterprise_code = #{enterpriseCode}

    AND record_time >= #{startDate}


    AND record_time <= #{endDate}


    ${dataScopeParams.dataScope}

SELECT to_char(b.contract_time, 'YYYY-MM') AS summaryMonth, SUM(hp.product_rmb_total_price) AS amount FROM ${tableName} hp LEFT JOIN ${signedContractTableName} b ON hp.signed_contract = b.primary_key WHERE hp.type = 1 AND hp.delete_flag = false AND hp.enterprise_code = #{enterpriseCode} AND hp.signed_contract IS NOT NULL AND b.contract_time IS NOT NULL
AND b.contract_time >= #{startDate}
AND b.contract_time <= #{endDate}
${dataScopeParams.dataScope}
GROUP BY to_char(b.contract_time, 'YYYY-MM') ORDER BY summaryMonth

SELECT to_char(record_time, 'YYYY-MM') AS summaryMonth,
       AVG(product_rmb_total_price)    AS amount
FROM ${tableName}
WHERE type = 0
  AND delete_flag = false
  AND enterprise_code = #{enterpriseCode}

    AND record_time >= #{startDate}


    AND record_time <= #{endDate}


    ${dataScopeParams.dataScope}

GROUP BY to_char(record_time, 'YYYY-MM')
ORDER BY summaryMonth

select SUM(product_rmb_total_price)
FROM ${tableName}
WHERE
type =3
AND delete_flag = false
AND enterprise_code = #{enterpriseCode}

    AND record_time >= #{startDate}


    AND record_time <= #{endDate}


    ${dataScopeParams.dataScope}

select staff,SUM(product_rmb_total_price) as total
from ${tableName}
WHERE
type =1
AND delete_flag = false
AND enterprise_code = #{enterpriseCode}

    AND record_time >= #{startDate}


    AND record_time <= #{endDate}


    AND staff IN

        #{staffCode}


GROUP BY
staff
ORDER BY
total DESC
LIMIT 10

select opposite,SUM(product_rmb_total_price) as total
from ${tableName}
WHERE
type =3
AND delete_flag = false
AND enterprise_code = #{enterpriseCode}

    AND record_time >= #{startDate}


    AND record_time <= #{endDate}

GROUP BY
opposite
ORDER BY
total DESC
LIMIT 10

