    product_total_price     = #{model.productTotalPrice},
    product_rmb_total_price = #{model.productRmbTotalPrice}
WHERE
    type = #{model.type}
  AND signed_contract = #{model.signedContract}
  AND contract_material = #{model.contractMaterial}
  AND enterprise_code = #{model.enterpriseCode}

